const app=document.querySelector('#app');
let state;try{state=JSON.parse(localStorage.getItem('bits-v1'))||{}}catch{state={}}
state={saved:[],answers:{},notes:{},...state};let page='explore',cat='all',current=questions[0],picked=null,collectionTab='saved',dIndex=0,dPicked=null,blend=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=c=>categories.find(x=>x[0]===c)[1];
function persist(){try{localStorage.setItem('bits-v1',JSON.stringify(state))}catch{document.querySelector('#save-status')?.replaceChildren(document.createTextNode('저장 공간을 사용할 수 없습니다.'))}document.querySelector('#saved-count').textContent=state.saved.length}
function go(p){page=p;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));render();window.scrollTo({top:0,behavior:'smooth'})}
function note(id,prompt){return `<div class="think"><label>생각해 보기</label>${esc(prompt)}</div><textarea aria-label="내 생각 기록" id="note" placeholder="떠오른 생각을 짧게 남겨 보세요.">${esc(state.notes[id]||'')}</textarea><button class="note-save" data-note="${id}">생각 저장 ↗</button> <span id="save-status" class="status" role="status"></span>`}
function sources(q){if(q.id==='q9')return '<p class="source-note">참고 · <a href="https://www.law.go.kr/법령/대한민국헌법/제27조" target="_blank" rel="noopener">대한민국헌법 제27조 제4항 ↗</a></p>';if(q.id==='q15')return '<p class="source-note">참고 · <a href="https://plato.stanford.edu/entries/informed-consent/" target="_blank" rel="noopener">Stanford Encyclopedia of Philosophy ↗</a></p>';return ''}
function quiz(){const q=current,answered=picked!==null;return `<section class="quiz ${answered?'revealed':''}" aria-label="퀴즈"><div class="quiz-top"><span class="pill">${name(q.cat)}</span><button class="bookmark ${state.saved.includes(q.id)?'on':''}" id="bookmark" aria-label="문제 저장" aria-pressed="${state.saved.includes(q.id)}">${state.saved.includes(q.id)?'저장됨':'저장'}</button></div><div class="question-stage"><h2 id="question-title" tabindex="-1">${q.q}</h2><p class="question-hint">${answered?'해설까지 보면 내 지식.':'알 것 같으면 선택. 몰라도 선택.'}</p></div><div class="answers">${q.options.map((a,i)=>`<button class="answer ${answered?(i===q.answer?'correct':i===picked?'wrong':'dimmed'):''}" data-answer="${i}" ${answered?'disabled':''}><i>${i+1}</i><span>${a}</span>${answered&&i===q.answer?'<em>정답</em>':''}</button>`).join('')}</div>${answered?`<div class="explanation" aria-live="polite"><div class="result-label">${picked===q.answer?'알고 있었네.':'지금 알았으니 됐다.'}<span>${picked===q.answer?'정답':'정답 '+(q.answer+1)}</span></div><p>${q.explanation}</p>${sources(q)}<details class="thought-detail"><summary>이걸 다른 데 써먹는다면? <span>+</span></summary>${note(q.id,q.prompt)}</details></div>`:''}<div class="quiz-bottom"><span class="keyboard-hint">1 · 2 · 3 선택 &nbsp; / &nbsp; → 다음</span><button class="${answered?'next':'quiet'}" id="next">${answered?'다음 잡지식':'건너뛰기'} <span>→</span></button></div></section>`}
function explore(){const done=Object.keys(state.answers).length;return `<div class="knowledge-topline"><details class="field-menu"><summary>분야 · ${name(cat)} <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 10 5 5 5-5"/></svg></summary><div class="category-menu" aria-label="분야 선택">${categories.map(c=>`<button class="category ${cat===c[0]?'active':''}" data-cat="${c[0]}" aria-pressed="${cat===c[0]}">${c[1]}<small>${c[0]==='all'?questions.length:questions.filter(q=>q.cat===c[0]).length}</small></button>`).join('')}</div></details><span class="reading-count">${done}개 알아둠</span></div><div id="quiz-slot">${quiz()}</div><div class="knowledge-links"><button data-go="dilemma">다른 관점 ↗</button><button id="blend">뜬금없는 연결 ↗</button><button data-go="collection">내 서랍 ↗</button></div>`}
function dilemma(){const d=dilemmas[dIndex];return `<div class="wide"><section class="intro"><div><div class="eyebrow">다른 관점</div><h1>다른 관점</h1><p>서로 다른 입장을 비교하는 질문입니다.</p></div></section><div class="quiz dilemma"><div class="quiz-top"><span class="pill">${d.tag}</span><span class="quiet">${dIndex+1} / ${dilemmas.length}</span></div><h2>${d.title}</h2><p>${d.text}</p><div class="choices">${[d.a,d.b].map((v,i)=>`<button data-choice="${i}" class="${dPicked===i?'selected':''}">${v}</button>`).join('')}</div><button class="text-link" id="show-views">${dPicked===null?'선택하지 않고 관점 보기 ↓':'다른 관점도 함께 살펴보세요'}</button>${dPicked!==null?`<div class="views">${d.views.map(v=>`<p>${v}</p>`).join('')}</div>${note('d'+dIndex,d.prompt)}`:''}<div class="quiz-bottom"><span>선택은 언제든 바꿀 수 있습니다.</span><button id="next-d" class="next">다음 질문 →</button></div></div></div>`}
function collection(){let list=questions.filter(q=>collectionTab==='saved'?state.saved.includes(q.id):collectionTab==='wrong'?state.answers[q.id]===false:!!state.notes[q.id]);return `<div class="wide"><section class="intro"><div><div class="eyebrow">보관함</div><h1>보관함</h1><p>저장한 문제, 오답과 메모를 확인하세요.</p></div></section><div class="toolbar">${[['saved','저장한 지식'],['wrong','틀린 문제'],['notes','생각 노트']].map(([id,label])=>`<button data-tab="${id}" class="${collectionTab===id?'active':''}">${label}</button>`).join('')}</div><input class="search" id="search" placeholder="질문이나 해설에서 검색" aria-label="저장한 콘텐츠 검색"><div id="items">${list.map(q=>`<article class="saved-item"><span class="pill">${name(q.cat)}</span><h3>${q.q}</h3><p>${collectionTab==='notes'?esc(state.notes[q.id]):q.explanation}</p><button class="text-link" data-open="${q.id}">다시 풀기 ↗</button></article>`).join('')}${collectionTab==='notes'?Object.entries(state.notes).filter(([id,v])=>!id.startsWith('q')&&v).map(([id,v])=>`<article class="saved-item"><span class="pill">${id.startsWith('d')?'다른 관점':'개념 연결'}</span><p>${esc(v)}</p></article>`).join(''):''}</div><div id="empty" class="empty" ${list.length||collectionTab==='notes'&&Object.keys(state.notes).length?'hidden':''}>${collectionTab==='wrong'?'틀린 문제가 아직 없어요.<br>문제를 풀면 복습할 내용이 여기에 모입니다.':'아직 모아 둔 내용이 없어요.<br>퀴즈의 저장 버튼을 누르거나 생각을 기록해 보세요.'}</div><p class="quiet" id="no-results" hidden>검색 결과가 없습니다.</p></div>`}
function connection(){let [a,b]=blend;return `<div class="wide"><section class="intro"><div><div class="eyebrow">개념 연결</div><h1>개념 연결</h1><p>두 개념을 비교하고 새로운 상황에 적용해 보세요.</p></div></section><section class="quiz"><div class="choices">${[a,b].map(q=>`<div class="saved-item" style="flex:1;margin:0"><span class="pill">${name(q.cat)}</span><h3>${q.q}</h3><p>${q.explanation}</p></div>`).join('')}</div>${note('b-'+a.id+'-'+b.id,'두 개념의 공통 원리는 무엇일까? 한쪽의 원리로 다른 쪽의 문제를 해결하는 아이디어를 적어 보세요.')}<div class="quiz-bottom"><button class="quiet" data-go="explore">← 탐색으로</button><button class="next" id="blend">다른 조합 ↗</button></div></section></div>`}
function render(){app.dataset.page=page;app.innerHTML=page==='explore'?explore():page==='dilemma'?dilemma():page==='collection'?collection():connection();persist()}
function next(){const pool=questions.filter(q=>cat==='all'||q.cat===cat);const unseen=pool.filter(q=>!(q.id in state.answers)&&q.id!==current.id);current=unseen.length?unseen[Math.floor(Math.random()*unseen.length)]:pool[(pool.findIndex(q=>q.id===current.id)+1)%pool.length];picked=null;render();window.labTransition?.();document.getElementById('quiz-overlay').scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelector('#question-title')?.focus({preventScroll:true})}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.page)go(b.dataset.page);if(b.dataset.go)go(b.dataset.go);if(b.dataset.cat){cat=b.dataset.cat;const pool=questions.filter(q=>cat==='all'||q.cat===cat);current=pool.find(q=>!(q.id in state.answers))||pool[0];picked=null;go('explore')}if(b.dataset.answer!==undefined&&picked===null){picked=Number(b.dataset.answer);state.answers[current.id]=picked===current.answer;persist();render();window.labFeedback?.(picked===current.answer)}if(b.id==='next')next();if(b.id==='bookmark'){const i=state.saved.indexOf(current.id);i<0?state.saved.push(current.id):state.saved.splice(i,1);persist();b.classList.toggle('on',i<0);b.setAttribute('aria-pressed',i<0);b.textContent=i<0?'저장됨':'저장'}if(b.dataset.note){const v=document.querySelector('#note').value.trim();if(v)state.notes[b.dataset.note]=v;else delete state.notes[b.dataset.note];persist();document.querySelector('#save-status').textContent='저장했어요.'}if(b.dataset.choice!==undefined){dPicked=Number(b.dataset.choice);render()}if(b.id==='show-views'){dPicked=dPicked===null?-1:dPicked;render()}if(b.id==='next-d'){dIndex=(dIndex+1)%dilemmas.length;dPicked=null;render()}if(b.dataset.tab){collectionTab=b.dataset.tab;render()}if(b.dataset.open){current=questions.find(q=>q.id===b.dataset.open);picked=null;cat='all';go('explore')}if(b.id==='blend'){const a=questions[Math.floor(Math.random()*questions.length)],pool=questions.filter(q=>q.cat!==a.cat);blend=[a,pool[Math.floor(Math.random()*pool.length)]];go('connection')}if(b.id==='motion'){document.body.classList.toggle('still');b.setAttribute('aria-pressed',document.body.classList.contains('still'))}});
document.addEventListener('input',e=>{if(e.target.id==='search'){let n=0;document.querySelectorAll('.saved-item').forEach(el=>{el.hidden=!el.textContent.toLowerCase().includes(e.target.value.toLowerCase());if(!el.hidden)n++});document.querySelector('#no-results').hidden=n>0||!e.target.value;document.querySelector('#empty').hidden=!!e.target.value||document.querySelectorAll('.saved-item').length>0}});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();go('explore')});render();

document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.repeat||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.target.isContentEditable)return;if(page!=='explore'||document.getElementById('quiz-overlay')?.hidden)return;if(['1','2','3'].includes(e.key)&&picked===null){e.preventDefault();document.querySelector('[data-answer="'+(Number(e.key)-1)+'"]')?.click()}if(e.key==='ArrowRight'){e.preventDefault();document.querySelector('#next')?.click()}});

window.startParkQuiz=function(category,questionId){
  cat=categories.some(c=>c[0]===category)?category:'all';
  const pool=questions.filter(q=>cat==='all'||q.cat===cat),unseen=pool.filter(q=>!(q.id in state.answers));
  current=pool.find(q=>q.id===questionId)||(unseen.length?unseen:pool)[Math.floor(Math.random()*(unseen.length||pool.length))];picked=null;go('explore');
};

window.getParkPreview=function(category){const pool=questions.filter(q=>q.cat===category),unseen=pool.filter(q=>!(q.id in state.answers)),items=unseen.length?unseen:pool;const q=items[Math.floor(Math.random()*items.length)];return q?{id:q.id,cat:q.cat,question:q.q,label:name(q.cat)}:null;};
